mapper.select:
select distinct s.id, s.inspection_route_name, s.`pause_cruise_flag`, s.route_status, s.creator, s.create_time, s.modifier, s.update_time from sys_inspection_route s where s.delete_flag = 0
and s.inspection_route_name like CONCAT('%', #{param.inspectionRouteName}, '%')
and s.creator like CONCAT('%', #{param.creator}, '%')
${param.dataScope}
and s.modifier like CONCAT('%',#{param.modifier},'%')
and s.create_time >= #{param.createTimeBegin}
and s.create_time <= #{param.createTimeEnd}
and s.update_time >= #{param.updateTimeBegin}
and s.update_time <= #{param.updateTimeEnd}
order by s.create_time
desc
asc
order by s.update_time
desc
asc
order by s.create_time desc

select s.id
from sys_inspection_route_fence_rel s
where
s.inspection_route_id = #{param.inspectionRouteId}
and s.delete_flag = 0
and s.tenant_id = #{param.tenantId}
and s.industry_code = #{param.industryCode}

select s.id, s.sort_seq, s.feature_id, s.duration_time, s.duration_unit, s.layer_id, s.plot_area, s.tbbh, l.custom_name as layer_name, l.geoserver_url, l.file_url, l.maxx, l.maxy, l.minx, l.miny, c.polygon_no, c.preset_name, c.preset_id, c.device_code, (case when length(IFNULL(ten.device_name,'')) = 0 then d.device_name else ten.device_name end) as deviceName, c.channel_code, (case when length(IFNULL(ten.channel_name,'')) = 0 then a.channel_name else ten.channel_name end) as channelName, c.polygon_points, c.polygon_id, c.monitor_area_id from sys_inspection_route_fence_rel s inner join vm_order_devices ord on s.device_code = ord.device_code and s.tenant_id = ord.tenant_id and s.industry_code = ord.industry_code and ord.ord_status in (0, 1, 2) and ord.accept_node = #{param.platformCode} and ord.delete_flag = 0 left join sys_layer l on s.layer_id = l.id and s.tenant_id = l.tenant_id and s.industry_code = l.industry_code left join vm_polygon_patch_config c on s.polygon_id = c.polygon_id and s.tenant_id = c.tenant_id and s.industry_code = c.industry_code and c.delete_flag = 0 left join vm_device_info_t d on ord.device_code = d.device_code and d.delete_flag = 0 left join vm_channel_info_t a on ord.device_code = a.device_code and s.channel_code = a.channel_code and a.delete_flag = 0 left join vm_tenant_device_channel_rel_t ten on ten.device_code = ord.device_code and ten.channel_code = s.channel_code and ten.tenant_id = ord.tenant_id and ten.delete_flag='0' and ten.industry_code = ord.industry_code where s.inspection_route_id = #{param.inspectionRouteId} and s.delete_flag = 0 and s.tenant_id = #{param.tenantId} and s.industry_code = #{param.industryCode}
${param.dataPermissions}
group by s.id order by s.sort_seq, s.id

select l.id, l.geoserver_url, l.layer_name, l.layer_namespace, l.custom_name, t.type_name, l.game_key, l.maxx, l.maxy, l.minx, l.miny, l.layer_type_id from sys_layer l left join sys_layer_type t on l.layer_type_id = t.id where l.tenant_id = #{param.tenantId} and l.industry_code = #{param.industryCode} and l.delete_flag = 0
and l.custom_name like CONCAT('%',#{param.customName},'%')
and l.layer_type_id = #{param.layerId}
${param.dataPermissions}

select
count(*)
from sys_inspection_route s
where s.inspection_route_name = #{param.inspectionRouteName}
and s.tenant_id = #{param.tenantId}
and s.industry_code = #{param.industryCode}
and s.delete_flag = 0

    and s.id != #{param.inspectionRouteId}

mapper.update:
update sys_inspection_route
set route_status = #{param.routeStatus}, modifier = #{param.modifier}, update_time = #{param.updateTime}
where id = #{param.id}

    and route_status = #{param.originalRouteStatus}

mapper.select:
select rel.id
from sys_inspection_route_fence_rel rel
inner join vm_order_devices o on rel.tenant_id = o.tenant_id and rel.industry_code = o.industry_code and rel.device_code = o.device_code
where rel.id = #{param.inspectionRouteSubId}
${param.dataScope}
limit 1

select rel.device_code, rel.channel_code, rel.preset_id, r.`pause_cruise_flag`
from sys_inspection_route_fence_rel rel inner join sys_inspection_route r on r.id = rel.inspection_route_id
where rel.id = #{id}

mapper.update:
update sys_inspection_route_fence_rel
set route_status = #{param.routeStatus},

    inspection_start_time = #{param.inspectionStartTime},


    pause_start_time = #{param.pauseStartTime},

modifier = #{param.modifier}, update_time = #{param.updateTime}
where id = #{param.id} and route_status = #{param.originalRouteStatus}

update sys_inspection_route
set route_status = 0, modifier = #{param.modifier}, update_time = #{param.updateTime}
where id = #{param.inspectionRouteId}

mapper.select:
select rel.feature_id, rel.plot_area,rel.inspection_route_id from sys_inspection_route r inner join sys_inspection_route_fence_rel rel on r.id = rel.inspection_route_id inner join sys_layer l on rel.layer_id = l.id where r.id in
#{id}
${dataPermissions}
group by rel.feature_id,rel.inspection_route_id

select id,
       inspection_route_name,
       route_status
from sys_inspection_route
    where id = #{param.inspectionRouteId}
        and tenant_id = #{param.tenantId}
        and industry_code = #{param.industryCode}
        and delete_flag = 0

select 
    from sys_inspection_route_fence_rel t
    inner join vm_order_devices o on t.tenant_id = o.tenant_id and t.industry_code = o.industry_code and t.device_code = o.device_code
where t.inspection_route_id = #{param.inspectionRouteId}
    and t.tenant_id = #{param.tenantId}
    and t.industry_code = #{param.industryCode}
    and t.delete_flag = 0
    and t.sort_seq > #{param.sortSeq}
    and o.ord_status in (0,1,2) and o.delete_flag = 0
    order by t.sort_seq
    limit 1

select rel.layer_id, rel.feature_id, de.device_code, cc.channel_code, rel.preset_id, rel.duration_time, rel.duration_unit, IFNULL(dr.device_name, de.device_name) AS device_name, IFNULL(dr.channel_name, cc.channel_name) AS channel_name, de.longitude, de.latitude, c.polygon_points, c.tbbh, layer.custom_name layerName, rel.id as inspection_route_sub_id, rel.inspection_route_id, rel.sort_seq, rel.route_status as status from sys_inspection_route_fence_rel rel inner join vm_order_devices ord on rel.device_code = ord.device_code and rel.tenant_id = ord.tenant_id and rel.industry_code = ord.industry_code and ord.ord_status in(0, 1, 2) and ord.delete_flag = 0 and ord.accept_node = #{param.platformCode} left join vm_device_info_t de on de.device_code = ord.device_code and de.delete_flag = 0 left join vm_polygon_patch_config c on rel.polygon_id = c.polygon_id and rel.tenant_id = c.tenant_id and rel.industry_code = c.industry_code and c.delete_flag = 0 left join sys_layer layer on layer.id = rel.layer_id and layer.tenant_id = rel.tenant_id and layer.industry_code = rel.industry_code and layer.delete_flag = 0 left join vm_tenant_device_channel_rel_t dr on dr.device_code = ord.device_code and dr.delete_flag = '0' AND dr.tenant_id = ord.tenant_id and dr.channel_code = rel.channel_code and dr.industry_code = ord.industry_code left join vm_channel_info_t cc on cc.device_code = ord.device_code and cc.channel_code = rel.channel_code and cc.delete_flag = 0 where rel.tenant_id = #{param.tenantId} and rel.industry_code = #{param.industryCode} and rel.inspection_route_id = #{param.inspectionRouteId} and rel.delete_flag = 0
${param.dataPermissions}
group by rel.id order by rel.sort_seq, rel.id

mapper.update:
update sys_inspection_route
set delete_flag = '1'
where id = #{param.inspectionRouteId}
and tenant_id = #{param.tenantId} and industry_code = #{param.industryCode}

update.foreach:
update sys_inspection_route_fence_rel
sort_seq = #{item.sortSeq}, duration_time = #{item.durationTime}, duration_unit = #{item.durationUnit}, modifier = #{item.modifier}, update_time = now()
where id = #{item.id}

mapper.select:
select count(*) from sys_inspection_route_fence_rel
where
polygon_id = #{param.polygonId}
and tenant_id = #{param.tenantId}
and industry_code = #{param.industryCode}
and delete_flag = 0

select case when IFNULL(max(polygon_no),0) = 0 then 0 else max(polygon_no) end
from vm_polygon_patch_config
where
device_code = #{param.deviceCode} and channel_code = #{param.channelCode}
and preset_id = #{param.presetId} and tenant_id = #{param.tenantId} and industry_code = #{param.industryCode}
and delete_flag = 0

select p.feature_id,s.id as inpectionRelId
from vm_polygon_patch_config p
left join sys_inspection_route_fence_rel s on p.polygon_id = s.polygon_id
and s.delete_flag = 0 and p.tenant_id = s.tenant_id and p.industry_code = s.industry_code
where p.delete_flag = 0
and p.layer_id = #{param.layerId}
and p.tenant_id = #{param.tenantId}
and p.industry_code = #{param.industryCode}
order by p.create_time desc,p.polygon_id desc

select count(*)
from sys_inspection_route
where tenant_id = #{tenantId} and industry_code = #{industryCode} and delete_flag = 0

    and create_time  >=  #{createTimeBegin}


    and create_time  <=  #{createTimeEnd}

select count(distinct rel.feature_id)
from sys_inspection_route r
inner join sys_inspection_route_fence_rel rel on r.id = rel.inspection_route_id
where r.tenant_id = #{tenantId} and r.industry_code = #{industryCode} and r.delete_flag = 0

    and r.create_time  >=  #{createTimeBegin}


    and r.create_time  <=  #{createTimeEnd}

mapper.update:
update sys_inspection_route_record
set end_time = #{param.endTime}, modifier = #{param.modifier},

    duration = duration + #{param.duration},


    start_time = #{param.startTime},

update_time = #{param.updateTime}
where id = #{param.id}

mapper.select:
select count(distinct r.id) inspectionRouteCount, count(distinct rel.feature_id) inspectPlotNum
from sys_inspection_route r
inner join sys_inspection_route_fence_rel rel on r.id = rel.inspection_route_id
where r.tenant_id = #{tenantId} and r.industry_code = #{industryCode} and r.delete_flag = 0

    and r.create_time >= #{startTime}


    and r.create_time <= #{endTime}

select IFNULL(sum(duration), 0) inspectionDuration, count(*) inspectionTimes
from sys_inspection_route_record
where tenant_id = #{tenantId} and industry_code = #{industryCode} and delete_flag = 0 and duration > 0

    and create_time >= #{startTime}


    and create_time <= #{endTime}
